extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    // Define the input and output filenames for the OpenEXR file to be fuzzed
    const char* inputFile = "input.exr";
    const char* outputFile = "fuzz.exr";

    // Open the input file in binary read mode to read the OpenEXR file data
    std::ifstream inputFile(inputFile, std::ios::in | std::ios::binary);
    if (!inputFile) {
        std::cerr << "Failed to open input file: " << inputFile << " " << std::error() << std::endl;
        return 1;
    }

    // Open the output file in binary write mode to write the fuzz data
    std::ofstream outputFile(outputFile, std::ios::out | std::ios::binary);
    if (!outputFile) {
        std::cerr << "Failed to open output file: " << outputFile << " " << std::error() << std::endl;
        return 1;
    }

    // Write the fuzz data to the output file
    outputFile.write(reinterpret_cast<const char*>(data), size);

    // Close the files before reading the OpenEXR header
    outputFile.close();
    inputFile.close();

    // Attempt to read the OpenEXR header
    OpenEXR::Header* header = OpenEXR::InputFile(outputFile, true);
    if (!header) {
        std::cerr << "Failed to read EXR file: " << std::error() << std::endl;
        return 1;
    }

    // Close the header and the input file
    header->close();
    inputFile.close();

    return 0;
}

