    if (!file) {
        std::cerr << "Open failed\n";
        return 0; // Indicate an error
    }

    // Attempting to read the header from the file
    auto header = Imf::Header();
    header = file.readHeader(header);
    if (!header) {
        std::cerr << "Failed to read header\n";
        return 0; // Indicate an error
    }

    // Attempting to create an image file
