    if (!image) {
        std::cerr << "Failed to create image\n";
        return 0; // Indicate an error
    }

    // Attempt to close the image and image file
    image.close();
    imageFile.close();

    // Attempting to close the input file
    file.close();

    return 0; // Indicate no error
