extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    try {
        // Convert the input data to an OpenEXR MemoryBuffer
        OpenEXR::MemoryBuffer buffer(data, size);
        OpenEXR::HeaderHandle* header = OpenEXR::HeaderDescription::default();

        // Create an InputFile to read the OpenEXR file
        OpenEXR::Imf::InputFile* inputFile = new OpenEXR::InputFile(buffer, header);

        // Create a Reader to read the image
        OpenEXR::ImageImf::Reader* imageReader = new OpenEXR::ImageImf::Reader(header, inputFile);

        // Read the image
        imageReader->read();

        // Clean up
        delete imageReader;
        delete inputFile;
        delete header;

    } catch (const OpenEXR::Imf::Exception& e) {
        std::cerr << "OpenEXR exception caught: " << e.what() << std::endl;

    } catch (const OpenEXR::IO::Exception& e) {
        std::cerr << "OpenEXR IO exception caught: " << e.what() << std::endl;

    } catch (const OpenEXR::Imath::Exception& e) {
        std::cerr << "Imath exception caught: " << e.what() << std::endl;

    } catch (const std::exception& e) {
        std::cerr << "General exception caught: " << e.what() << std::endl;
    }

    return 0;
}

